CurrentRates = {
    init: async function(app, container) {
        var rates = (await api.get("B2B/Rate/Current()")).value;
        var list = $("[name=rateList]", container);

        var charts = await Promise.all(rates.map(async rate => {
            list.append(`<tr>
                <td>${rate.Description}</td>
                <td>${rate.Value}%</td>
                <td><div name="rate-chart-${rate.Id}"></div></td>
            </tr>`);

            return CurrentRates.initChart(
                $(`[name=rate-chart-${rate.Id}]`, list),
                await CurrentRates.getData(rate)
            );
        }));

		$(window).resize(function () {
            charts.forEach(chart => {
                chart.kendoObject.refresh();
            });
		});
    },

	initChart: function (container, data) {
        return container.kendoChart({
            chartArea: {
                width: 120,
                height: 28,
                margin: 0,
                background: "transparent"
            },
            plotArea: {
                margin: 0
            },
            legend: {
                visible: false
            },
            seriesDefaults: {
                type: "line",
                style: "smooth",
                markers: { visible: false },
                tooltip: { visible: true }
            },
            series: [{
                data: data.rates,
                color: "#006f9f",
                width: 2
            }],
            categoryAxis: {
                visible: false,
                majorGridLines: { visible: false }
            },
            valueAxis: {
                visible: false,
                majorGridLines: { visible: false },
                minorGridLines: { visible: false }
            },
            transitions: false,
            tooltip: {
                visible: true,
                template: function (data) { return "" + (kendo.toString(data.value, 'n2')) + "%"; }
            }
        }).data("kendoChart");
    },

	getData: async function(rate) {
        console.log('get data', rate.Name);
		var history = (await api.get(`B2B/Rate?$orderBy=AppliesFrom desc&$filter=Name eq '${rate.Name}'&$top=12`)).value;
		
		history = history.reverse()
			.map(r => {
				r.formatted = kendo.toString(r.AppliesFrom, 'dd-MM-yyyy');
                return r;
			})
			.sort((a, b) => a.AppliesFrom - b.AppliesFrom);
		
		var categories = [... new Set(history.map(t => t.formatted))];
		
		return {
			rates: categories.map(m => history
				.filter(s => s.formatted == m)
				.map(s => s.Value)
				.reduce((accumulator, current) => accumulator + current, 0))
		};
	}
}
